var scene=UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/MainMenu.unity",UnityEditor.SceneManagement.OpenSceneMode.Additive);try{return scene.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<TMPro.TMP_Text>(true)).Where(t=>t.enabled&&t.GetComponentInParent<UnityEngine.UI.Button>()!=null&&t.font!=GameFonts.Title).Select(t=>new{name=t.name,parent=t.transform.parent.name,font=t.font.name,text=t.text}).ToArray();}finally{UnityEditor.SceneManagement.EditorSceneManager.CloseScene(scene,true);}
